class CustomerProfileAdmin(admin.ModelAdmin):
    def get_urls(self):
        urls = super().get_urls()
        custom_urls = [
            path('<int:profile_id>/export-ssn/', self.admin_site.admin_view(self.export_ssn_dossier)),
        ]
        return custom_urls + urls

    def export_ssn_dossier(self, request, profile_id):
        profile = get_object_or_404(CustomerProfile, id=profile_id)
        if not self.has_change_permission(request, profile) or not request.user.has_perm('customers.can_view_pii'):
            raise PermissionDenied()
        return JsonResponse({'full_name': profile.user.get_full_name(), 'tax_id': profile.ssn_plaintext})
